package store.cadera.cdrjobs.api.event;
import org.bukkit.entity.Player;import org.bukkit.event.Event;import org.bukkit.event.HandlerList;import org.jetbrains.annotations.NotNull;import store.cadera.cdrjobs.api.ProfessionActionType;import store.cadera.cdrjobs.model.JobType;
public final class ProfessionActionEvent extends Event {private static final HandlerList HANDLERS=new HandlerList();private final Player player;private final JobType profession;private final ProfessionActionType action;private final long amount;public ProfessionActionEvent(Player p,JobType j,ProfessionActionType a,long amount){player=p;profession=j;action=a;this.amount=amount;}public Player getPlayer(){return player;}public JobType getProfession(){return profession;}public ProfessionActionType getAction(){return action;}public long getAmount(){return amount;}@Override public @NotNull HandlerList getHandlers(){return HANDLERS;}public static HandlerList getHandlerList(){return HANDLERS;}}
